begin;
create extension if not exists pgtap with schema extensions;
set local search_path to public,extensions;
select plan(24);
insert into auth.users(id,email) values('30000000-0000-0000-0000-000000000001','payments-owner@example.test'),('30000000-0000-0000-0000-000000000002','payments-other@example.test');
set local role authenticated;
select set_config('request.jwt.claims','{"sub":"30000000-0000-0000-0000-000000000001","role":"authenticated"}',true);
select public.create_business('Payment test','','{plumbing}','flat',0);
reset role;
create temp table payment_fixture as select business_id as bid,'30000000-0000-0000-0000-000000000003'::uuid as job from public.business_members where user_id='30000000-0000-0000-0000-000000000001';
grant select on payment_fixture to authenticated;
update public.businesses set alternative_methods='{"cash":""}' where id=(select bid from payment_fixture);
insert into public.customers(id,business_id,name) select '30000000-0000-0000-0000-000000000004',bid,'Customer' from payment_fixture;
insert into public.jobs(id,business_id,customer_id,title) select job,bid,'30000000-0000-0000-0000-000000000004','Bathroom' from payment_fixture;
insert into public.estimates(id,business_id,job_id,number,deposit_bps) select '30000000-0000-0000-0000-000000000005',bid,job,'E-TEST',3000 from payment_fixture;
insert into public.estimate_lines(business_id,estimate_id,description,unit,qty_hundredths,unit_cents) select bid,'30000000-0000-0000-0000-000000000005','Bathroom','flat',100,100000 from payment_fixture;
update public.estimates set sent_at=now(),tax_rate_bps=0,tax_labor=false,tax_materials=false where id='30000000-0000-0000-0000-000000000005';
set local role authenticated;
select set_config('request.jwt.claims','{"sub":"30000000-0000-0000-0000-000000000001","role":"authenticated"}',true);
select public.sign_estimate(job,'Customer','test') from payment_fixture;
select public.create_job_payment_request('30000000-0000-0000-0000-000000000006',job,'milestone',20000,'Rough in') from payment_fixture;
select public.create_job_payment_request('30000000-0000-0000-0000-000000000007',job,'milestone',80000,'Finish') from payment_fixture;
reset role;
select lives_ok($$select public.reserve_job_payment('30000000-0000-0000-0000-000000000006','wallet')$$,'first online attempt reserves method');
select throws_ok($$select public.record_job_payment('30000000-0000-0000-0000-000000000006','pi_test123456',20000,'wallet','succeeded')$$,'P0001','Payment does not match','unbound intent cannot credit ledger');
select throws_ok($$select public.reserve_job_payment('30000000-0000-0000-0000-000000000006','bank')$$,'P0001','Use the original payment method','second payment method cannot produce another charge');
set local role authenticated;
select throws_ok($$select public.record_job_cash('30000000-0000-0000-0000-000000000006')$$,'P0001','An online payment was started','cash cannot race an online reservation');
reset role;
update public.job_payment_requests set intent_id='pi_test123456' where id='30000000-0000-0000-0000-000000000006';
select throws_ok($$update public.job_payment_requests set intent_id='pi_other123456' where id='30000000-0000-0000-0000-000000000006'$$,
  'P0001','Payment intent already bound','a second Stripe intent cannot replace a bound advance intent');
select lives_ok($$select public.record_job_payment('30000000-0000-0000-0000-000000000006','pi_test123456',20000,'wallet','failed')$$,'a failed Stripe attempt is recorded');
set local role authenticated;
insert into public.change_orders(id,business_id,job_id,number,description,amount_cents,base_cents,sent_at) select '30000000-0000-0000-0000-000000000008',bid,job,1,'Removed fixture',-10000,100000,now() from payment_fixture;
select public.sign_change_order('30000000-0000-0000-0000-000000000008','Customer','test');
reset role;
select throws_ok($$select public.reserve_job_payment('30000000-0000-0000-0000-000000000007','wallet')$$,'P0001','Nothing due','another unresolved advance counts against reduced agreed total');
set local role authenticated;
insert into public.invoices(id,business_id,job_id,number) select '30000000-0000-0000-0000-000000000009',bid,job,'I-INTEGRITY' from payment_fixture;
insert into public.invoice_lines(business_id,invoice_id,description,kind,qty_hundredths,unit_cents) select bid,'30000000-0000-0000-0000-000000000009','Agreed work','labor',100,100000 from payment_fixture;
insert into public.invoice_lines(business_id,invoice_id,description,kind,qty_hundredths,unit_cents) select bid,'30000000-0000-0000-0000-000000000009','Approved credit','fee',100,-10000 from payment_fixture;
update public.invoices set sent_at=now(),tax_rate_bps=0,tax_labor=false,tax_materials=false,issued_on=current_date,due_days=0 where id='30000000-0000-0000-0000-000000000009';
select ok(not has_function_privilege('authenticated','public.reserve_invoice_email(uuid,uuid)','execute'),'business clients cannot manufacture email attempts');
select throws_ok($$select public.mark_invoice_paid('30000000-0000-0000-0000-000000000009',100000)$$,'P0001','Wait for the online payment','failed retryable advance still blocks cash final');
reset role;
select is(public.reserve_invoice_email('30000000-0000-0000-0000-000000000009','30000000-0000-0000-0000-000000000011'),true,'first explicit email reserves one attempt');
select is(public.reserve_invoice_email('30000000-0000-0000-0000-000000000009','30000000-0000-0000-0000-000000000011'),false,'retry does not reserve a second email');
select throws_ok($$select public.reserve_invoice_email('30000000-0000-0000-0000-000000000009','30000000-0000-0000-0000-000000000012')$$,'PT429','wait before resending','another immediate send is throttled');
select throws_ok($$select public.reserve_invoice_payment('30000000-0000-0000-0000-000000000009','wallet')$$,'P0001','Wait for the online payment','failed retryable advance still blocks online final');
select lives_ok($$select public.record_job_payment('30000000-0000-0000-0000-000000000006','pi_test123456',20000,'wallet','succeeded')$$,'retry of same advance may succeed');
select is(public.reserve_invoice_payment('30000000-0000-0000-0000-000000000009','wallet'),70000,'final reservation deducts confirmed advance');
select throws_ok($$select public.reserve_invoice_payment('30000000-0000-0000-0000-000000000009','bank')$$,'P0001','Use the original payment method','final method remains frozen');
update public.invoice_payment_reservations set intent_id='pi_final123456' where invoice_id='30000000-0000-0000-0000-000000000009';
select lives_ok($$update public.invoice_payment_reservations set intent_id='pi_final123456' where invoice_id='30000000-0000-0000-0000-000000000009'$$,
  'retrying the same intent binding succeeds');
select throws_ok($$update public.invoice_payment_reservations set intent_id='pi_other123456' where invoice_id='30000000-0000-0000-0000-000000000009'$$,
  'P0001','Payment intent already bound','a second Stripe intent cannot replace a bound invoice intent');
select throws_ok($$select public.record_stripe_payment((select bid from payment_fixture),'30000000-0000-0000-0000-000000000009','pi_wrong123456',70000,'wallet','succeeded',100000)$$,'P0001','Payment does not match reservation','different intent cannot claim reserved payment');
select lives_ok($$select public.record_stripe_payment((select bid from payment_fixture),'30000000-0000-0000-0000-000000000009','pi_final123456',70000,'wallet','succeeded',100000)$$,'reserved final intent can settle');
select lives_ok($$select public.record_stripe_payment((select bid from payment_fixture),'30000000-0000-0000-0000-000000000009','pi_final123456',70000,'wallet','processing',100000)$$,'late processing notice is accepted idempotently');
select is((select status from public.payments where stripe_payment_intent='pi_final123456'),'succeeded','late notice never downgrades confirmed money');
select is((select count(*)::int from public.payments),2,'one advance and one final payment only');
select is((select sum(amount_cents)::int from public.payments where status='succeeded'),90000,'job fully reconciles without duplicate credits');
select * from finish();
rollback;
